insert into public.teams (season_id, name)
select s.id, v.team_name
from public.seasons s
cross join (values
  ('ROBS ROVERS'),
  ('RASH IN THE ATTIC'),
  ('SHEFSPANYOL'),
  ('DURHAM DYNAMO'),
  ('FC WALES'),
  ('AMALGA SANTOS'),
