insert into public.goalkeeper_memberships (
  season_id, team_id, goalkeeper_club_id, acquired_at, released_at
)
select s.id, t.id, g.id,
  (coalesce(v.acquired_date, '2019-08-01') || 'T00:00:00.000Z')::timestamptz,
  case
    when v.sold_date is null then null
    else (v.sold_date || 'T23:59:59.000Z')::timestamptz
  end
from public.seasons s
join public.teams t on t.season_id = s.id and s.name = '2019/2020'
