insert into public.cup_ties (
  season_id, competition, round_name, home_team_id, away_team_id, home_name, away_name, home_score, away_score, played_on
)
select s.id, v.competition, v.round_name,
  ht.id, at.id, v.home_name, v.away_name,
  v.home_score, v.away_score, v.played_on::date
from public.seasons s
join (values
  ('dream_league_cup', '1st Round Qualifier', 'DURHAM DYNAMO', 'ERIMUS', 'DURHAM DYNAMO', 'ERIMUS', -2, 1, null),
  ('dream_league_cup', '2nd Round', 'ROBS ROVERS', 'SHOW ME THE MANE', 'ROBS ROVERS', 'SHOW ME THE MANE', 1, -2, null),
  ('dream_league_cup', '2nd Round', 'SHEFSPANYOL', 'ERIMUS', 'SHEFSPANYOL', 'ERIMUS', 0, 2, null),
  ('dream_league_cup', '2nd Round', 'AMALGA SANTOS', 'FC WALES', 'AMALGA SANTOS', 'FC WALES', 1, 2, null),
  ('dream_league_cup', '2nd Round', 'MCTOMINATOR', 'RASH IN THE ATTIC', 'MCTOMINATOR', 'RASH IN THE ATTIC', 2, 2, null),
  ('dream_league_cup', '2nd Round Replay', 'MCTOMINATOR', 'RASH IN THE ATTIC', 'MCTOMINATOR', 'RASH IN THE ATTIC', null, null, null)
) as v(competition, round_name, home_team, away_team, home_name, away_name, home_score, away_score, played_on)
  on s.name = '2019/2020'
left join public.teams ht
  on ht.season_id = s.id and ht.name = v.home_team
left join public.teams at
  on at.season_id = s.id and at.name = v.away_team;

insert into public.honours (season_id, team_id, title, season_label)
select s.id, t.id, v.title, v.season_label
from public.seasons s
join (values
  ('ROBS ROVERS', 'League Champions', '19/20'),
  ('RASH IN THE ATTIC', 'Cup Winners', '19/20')
) as v(team_name, title, season_label)
  on s.name = '2019/2020'
join public.teams t on t.season_id = s.id and t.name = v.team_name;

commit;

